// Resume el resultado de POST /ingest/run (objeto IngestRun del contrato de API).
const r = $input.first().json || {};
const fallo = Boolean(r.error) && !r.status;            // error de red/HTTP del nodo anterior
const resumen = {
  ejecutado_en: new Date().toISOString(),
  estado: fallo ? 'error' : (r.status || 'desconocido'),
  lineas_leidas: r.lines_read ?? 0,
  logs_insertados: r.logs_inserted ?? 0,
  errores_de_parseo: r.parse_errors ?? 0,
  hallazgos_creados: r.findings_created ?? 0,
  ruido_descartado: r.findings_noise ?? 0,
  error: fallo ? (r.error.message || String(r.error)) : (r.error ?? null),
};
resumen.hay_hallazgos = resumen.hallazgos_creados > 0;
resumen.texto = `Ingesta ${resumen.estado}: ${resumen.logs_insertados} logs nuevos, ` +
  `${resumen.hallazgos_creados} hallazgos, ${resumen.ruido_descartado} descartados como ruido` +
  (resumen.error ? ` | ERROR: ${resumen.error}` : '');
console.log(resumen.texto);   // queda en los logs de n8n y en la ejecucion
return [{ json: resumen }];

// ILUSTRATIVO: reproduce en n8n el calculo del caso (beaconing por regularidad + puertos inusuales)
// sobre una MUESTRA sintetica. El calculo AUTORITATIVO vive en el backend (detectores deterministas).
const CV_MAX = 0.25;          // umbral de coeficiente de variacion (igual que beacon_max_cv)
const MIN_CONN = 10;          // minimo de conexiones (beacon_min_connections)
const COMMON_PORTS = new Set([22, 25, 53, 80, 123, 443, 587, 993, 995, 8080]);
const UNUSUAL_MIN_CONN = 3;   // unusual_port_min_connections

// PRNG determinista para que la muestra sea reproducible
let seed = 42;
const rnd = () => (seed = (seed * 1664525 + 1013904223) % 4294967296) / 4294967296;

function serie(n, base, jitter) { let t = 0; const ts = []; for (let i = 0; i < n; i++) { ts.push(t); t += base + (rnd() * 2 - 1) * jitter; } return ts; }
function irregular(n) { let t = 0; const ts = []; for (let i = 0; i < n; i++) { ts.push(t); t += 5 + rnd() * 600; } return ts; }

const muestra = [
  { src: '10.0.0.5', dst: '185.1.2.3',   port: 443,  ts: serie(30, 60, 2) },   // latido cada ~60 s
  { src: '10.0.0.7', dst: '151.101.1.1', port: 443,  ts: irregular(30) },        // navegacion humana
  { src: '10.0.0.9', dst: '203.0.113.7', port: 4444, ts: irregular(6) },         // puerto inusual
];

const mean = a => a.reduce((s, x) => s + x, 0) / a.length;
const stdev = a => { const m = mean(a); return Math.sqrt(mean(a.map(x => (x - m) ** 2))); };

return muestra.map(c => {
  const iv = c.ts.slice(1).map((t, i) => t - c.ts[i]);
  const m = iv.length ? mean(iv) : 0;
  const s = iv.length ? stdev(iv) : 0;
  const cv = m > 0 ? s / m : null;
  const esBeacon = c.ts.length >= MIN_CONN && cv !== null && cv <= CV_MAX;
  const inusual = !COMMON_PORTS.has(c.port) && c.ts.length >= UNUSUAL_MIN_CONN;
  return { json: {
    src: c.src, dst: c.dst, puerto: c.port, conexiones: c.ts.length,
    intervalo_medio_s: Number(m.toFixed(2)), desviacion_s: Number(s.toFixed(2)),
    cv: cv === null ? null : Number(cv.toFixed(3)),
    beaconing: esBeacon, puerto_inusual: inusual,
    nota: 'Muestra ilustrativa; el veredicto real lo calcula el backend.',
  } };
});
